// Expo config plugin: release signing and version code for the generated android/ project.
//
// android/ is generated by `expo prebuild` and never committed, so the release signing lives here.
// The generated app/build.gradle signs release builds with the debug key; this plugin makes it:
//   - sign `release` with the upload key when all four values are set, read from environment
//     variables (or Gradle properties with the same names):
//       ANDROID_SIGNING_STORE_FILE  absolute path of the keystore (decoded to a temporary file)
//       SIGNING_STORE_PASSWORD      keystore password
//       SIGNING_KEY_ALIAS           key alias
//       SIGNING_KEY_PASSWORD        key password
//   - fail the build when `-PrequireReleaseSigning=true` is passed and any value is missing, so a
//     distributed APK can never be signed with the debug key by accident;
//   - fall back to the debug key otherwise (local release checks on an emulator), with a warning;
//   - take the version code from `-PappVersionCode=<n>` (default: android.versionCode in app.json).
// No secret is written into the project: Gradle reads them at build time from the environment that
// `doppler run` provides (see scripts/distribute-android.sh and docs/distribution.md).
const { withAppBuildGradle } = require('expo/config-plugins');

const MARKER = '// kinfall: release signing (plugins/withReleaseSigning.js)';

const HELPER = `${MARKER}
def signingValue = { String name ->
    def value = System.getenv(name) ?: findProperty(name)
    return value ? value.toString() : null
}
def releaseSigning = [
    storeFile: signingValue('ANDROID_SIGNING_STORE_FILE'),
    storePassword: signingValue('SIGNING_STORE_PASSWORD'),
    keyAlias: signingValue('SIGNING_KEY_ALIAS'),
    keyPassword: signingValue('SIGNING_KEY_PASSWORD'),
]
def releaseSigningReady = releaseSigning.values().every { it != null && !it.isEmpty() }
if (!releaseSigningReady && (findProperty('requireReleaseSigning') ?: 'false').toBoolean()) {
    throw new GradleException('Release signing is required but ANDROID_SIGNING_STORE_FILE, SIGNING_STORE_PASSWORD, SIGNING_KEY_ALIAS or SIGNING_KEY_PASSWORD is missing. Run the build through scripts/distribute-android.sh.')
}

`;

const RELEASE_SIGNING_CONFIG = `
        release {
            if (releaseSigningReady) {
                storeFile file(releaseSigning.storeFile)
                storePassword releaseSigning.storePassword
                keyAlias releaseSigning.keyAlias
                keyPassword releaseSigning.keyPassword
            }
        }`;

function applyReleaseSigning(gradle) {
  if (gradle.includes(MARKER)) return gradle;
  let out = gradle;

  const androidBlock = /\nandroid \{\n/;
  if (!androidBlock.test(out)) throw new Error('withReleaseSigning: no android { block in app/build.gradle');
  out = out.replace(androidBlock, `\n${HELPER}android {\n`);

  const debugSigning = /(signingConfigs \{\n\s+debug \{[^}]*\})/;
  if (!debugSigning.test(out)) throw new Error('withReleaseSigning: no signingConfigs.debug in app/build.gradle');
  out = out.replace(debugSigning, `$1${RELEASE_SIGNING_CONFIG}`);

  const releaseUsesDebug = /(release \{\n(?:\s*\/\/[^\n]*\n)*)(\s+)signingConfig signingConfigs\.debug/;
  if (!releaseUsesDebug.test(out)) throw new Error('withReleaseSigning: release build type does not use signingConfigs.debug');
  out = out.replace(
    releaseUsesDebug,
    `$1$2if (!releaseSigningReady) logger.warn('Release build signed with the DEBUG key: not for distribution.')\n$2signingConfig releaseSigningReady ? signingConfigs.release : signingConfigs.debug`,
  );

  const versionCode = /versionCode (\d+)/;
  if (!versionCode.test(out)) throw new Error('withReleaseSigning: no versionCode in app/build.gradle');
  out = out.replace(versionCode, "versionCode((findProperty('appVersionCode') ?: '$1').toString().toInteger())");

  return out;
}

module.exports = function withReleaseSigning(config) {
  return withAppBuildGradle(config, (cfg) => {
    if (cfg.modResults.language !== 'groovy') throw new Error('withReleaseSigning: expected a Groovy app/build.gradle');
    cfg.modResults.contents = applyReleaseSigning(cfg.modResults.contents);
    return cfg;
  });
};

module.exports.applyReleaseSigning = applyReleaseSigning;
